Here is the root cause:
The bug was caused by the `ecc_digits_from_bytes` function reading too many bytes from the input byte array when an insufficient number of bytes were provided to fill the output digit array. This could lead to uninitialized or incorrect values in the output array, as the function did not properly handle cases where the number of input bytes was less than required for the specified number of output digits.

Here is the patch:

+void ecc_digits_from_bytes(const u8 *in, unsigned int nbytes,
+			   u64 *out, unsigned int ndigits)
+{
+	int diff = ndigits - DIV_ROUND_UP(nbytes, sizeof(u64));
+	unsigned int o = nbytes & 7;
+	__be64 msd = 0;
+
+	/* diff > 0: not enough input bytes: set most significant digits to 0 */
+	if (diff > 0) {
+		ndigits -= diff;
+		memset(&out[ndigits - 1], 0, diff * sizeof(u64));
+	}
+
+	if (o) {
+		memcpy((u8 *)&msd + sizeof(msd) - o, in, o);
+		out[--ndigits] = be64_to_cpu(msd);
+		in += o;
+	}
+	ecc_swap_digits(in, out, ndigits);
+}
+EXPORT_SYMBOL(ecc_digits_from_bytes);
+
 static u64 *ecc_alloc_digits_space(unsigned int ndigits)
 {
 	size_t len = ndigits * sizeof(u64);

 	if (!len)
 		return NULL;

 	return kmalloc(len, GFP_KERNEL);
 }



